require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';
$roles=$pdo->query("SELECT j.*,COUNT(rs.role_skill_id) AS skill_count FROM job_roles j LEFT JOIN role_skills rs ON rs.job_role_id=j.job_role_id WHERE j.is_active=1 GROUP BY j.job_role_id ORDER BY j.career_field,j.role_name")->fetchAll();
$savedStmt=$pdo->prepare('SELECT job_role_id FROM saved_job_roles WHERE user_id=?');$savedStmt->execute([(int)current_user()['user_id']]);$saved=array_flip(array_map('intval',$savedStmt->fetchAll(PDO::FETCH_COLUMN)));
$icons=['Cloud Engineer'=>'☁','AI / Machine Learning Engineer'=>'✧','Frontend Developer'=>'◫','Backend Developer'=>'⌘','Cybersecurity Analyst'=>'⬡','DevOps Engineer'=>'⟳'];
$pageTitle='Career explorer';$active='careers';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Find your direction</span><h1 class="h1">Explore career paths</h1><p>Compare career roles, understand the skills involved and choose a direction to assess.</p></div></div><div class="filters"><div class="search-box"><span>⌕</span><input type="search" placeholder="Search career roles or fields…" data-search-input="#role-grid"></div><span class="pill pill-blue"><?=count($roles)?> starter roles</span></div>
<div class="role-grid" id="role-grid"><?php foreach($roles as $r):?><article class="card role-card" data-search-item><div class="row-between"><div class="role-icon"><?=h($icons[$r['role_name']]??'✦')?></div><?php if(isset($saved[(int)$r['job_role_id']])):?><span class="pill pill-green">Saved</span><?php endif;?></div><h3><?=h($r['role_name'])?></h3><p><?=h($r['short_description'])?></p><div class="tag-row"><span class="tag"><?=h($r['career_field'])?></span><span class="tag"><?=$r['skill_count']?> mapped skills</span></div><div class="role-meta"><span>Career profile</span><a class="link-arrow" href="<?=h(url('careers/view.php?id='.(int)$r['job_role_id']))?>">Explore role →</a></div></article><?php endforeach;?></div>
